"use strict";exports.type="visitor",exports.name="removeUnusedNS",exports.active=!0,exports.description="removes unused namespaces declaration",exports.fn=()=>{const e=new Set;return{element:{enter:(t,s)=>{if("svg"===t.name&&"root"===s.type)for(const s of Object.keys(t.attributes))if(s.startsWith("xmlns:")){const t=s.slice(6);e.add(t)}if(0!==e.size){if(t.name.includes(":")){const[s]=t.name.split(":");e.has(s)&&e.delete(s)}for(const s of Object.keys(t.attributes))if(s.includes(":")){const[t]=s.split(":");e.delete(t)}}},exit:(t,s)=>{if("svg"===t.name&&"root"===s.type)for(const s of e)delete t.attributes[`xmlns:${s}`]}}}};